import { useEffect, useState } from "react";
import socket from "../socket";
import api from "../api";
import { useToast } from "../context/ToastContext";
import Skeleton from "../components/Skeleton";
import "../components/skeleton.css";

export default function Provider() {
  const [req, setReq] = useState(null);
  const [providerId, setProviderId] = useState("");
  const [bookings, setBookings] = useState([]);
  const [loading, setLoading] = useState(true);
  const { addToast } = useToast();

  const loadProviderBookings = async () => {
    if (!providerId) return;
    setLoading(true);
    try {
      const response = await api.get("/bookings/provider-bookings");
      setBookings(response.data || []);
      const assigned = response.data?.find((booking) => booking.status === "assigned" || booking.status === "pending");
      if (assigned) {
        setReq(assigned);
      }
    } catch (err) {
      console.error("Error loading provider bookings:", err);
      addToast("Unable to load your booking requests", "error");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {

  fetchBookings();

  socket.on("booking-created", (data) => {

    console.log("NEW BOOKING:", data);

    alert(
      `New Booking: ${data.booking.serviceName}`
    );

    fetchBookings();

  });

  return () => {
    socket.off("booking-created");
  };

}, []);

  // Emit live location while provider is online
  useEffect(() => {
    if (!providerId || !navigator.geolocation) return;

    const watchId = navigator.geolocation.watchPosition(
      (position) => {
        const payload = {
          providerId,
          lat: position.coords.latitude,
          lng: position.coords.longitude
        };
        socket.emit("provider-location", payload);
      },
      (err) => console.warn("Provider geolocation error:", err),
      { enableHighAccuracy: true }
    );

    return () => navigator.geolocation.clearWatch(watchId);
  }, [providerId]);

  const handleAccept = () => {
    socket.emit("booking-response", { bookingId: req && req._id, status: "accepted", providerId: providerId });
    setReq(null);
  };

  const handleReject = () => {
    socket.emit("booking-response", { bookingId: req && req._id, status: "rejected", providerId: providerId });
    setReq(null);
  };

  const activeBookings = bookings.filter((booking) => booking.status !== "completed" && booking.status !== "cancelled");
  const activeRequest = req || activeBookings.find((booking) => booking.status === "assigned" || booking.status === "pending");
  const otherBookings = activeBookings.filter((booking) => booking._id !== activeRequest?._id);

  return (
    <div className="dashboard-container">
      <header className="dashboard-header">
        <div className="dashboard-logo">🚀 FastAid</div>
        <button className="logout-btn" onClick={() => {
          localStorage.removeItem("token");
          window.location.href = "/";
        }}>
          Logout
        </button>
      </header>
      <div className="dashboard-content">
        <h1 className="dashboard-title">Provider Dashboard 🛠️</h1>
        <p className="dashboard-subtitle">Manage your service requests</p>

        {loading ? (
          <div className="no-requests">
            <div className="no-requests-icon">🔔</div>
            <div className="no-requests-text">Loading your bookings…</div>
            <div style={{ marginTop: 14 }}>
              <Skeleton count={3} height="80px" />
            </div>
          </div>
        ) : activeRequest ? (
          <div className="provider-request-card">
            <div className="provider-request-title">Service: {activeRequest.serviceName || activeRequest.serviceId?.name}</div>
            <p style={{ fontSize: '16px', marginBottom: '10px' }}>📍 Location: {activeRequest.location || activeRequest.locationDetails?.fullAddress}</p>
            <p style={{ fontSize: '14px', opacity: 0.9 }}>Customer: {activeRequest.userId?.name || activeRequest.userId || 'Unknown'}</p>
            <p style={{ fontSize: '14px', opacity: 0.9 }}>Status: {activeRequest.status}</p>
            <div className="provider-buttons">
              {(activeRequest.status === 'assigned' || activeRequest.status === 'pending') && (
                <>
                  <button className="provider-btn provider-btn-accept" onClick={handleAccept}>
                    ✅ Accept Request
                  </button>
                  <button className="provider-btn provider-btn-reject" onClick={handleReject}>
                    ❌ Reject Request
                  </button>
                </>
              )}
            </div>
          </div>
        ) : (
          <div className="no-requests">
            <div className="no-requests-icon">🔔</div>
            <div className="no-requests-text">No active service requests</div>
            <p style={{ marginTop: '10px', color: '#6B7280' }}>Waiting for new bookings...</p>
            <div style={{ marginTop: 14 }}>
              <Skeleton count={2} height="80px" />
            </div>
          </div>
        )}

        {otherBookings.length > 0 && (
          <div className="booking-list">
            <h2 className="section-title">Other Active Bookings</h2>
            {otherBookings.map((booking) => (
              <div key={booking._id} className="booking-card">
                <h4>{booking.serviceName || booking.serviceId?.name}</h4>
                <p>Customer: {booking.userId?.name || booking.userId}</p>
                <p>Status: {booking.status}</p>
                <p>Location: {booking.location || booking.locationDetails?.fullAddress}</p>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );

  return (
    <div className="dashboard-container">
      <header className="dashboard-header">
        <div className="dashboard-logo">🚀 FastAid</div>
        <button className="logout-btn" onClick={() => {
          localStorage.removeItem("token");
          window.location.href = "/";
        }}>
          Logout
        </button>
      </header>
      <div className="dashboard-content">
        <h1 className="dashboard-title">New Service Request 🔔</h1>
        
        <div className="provider-request-card">
          <div className="provider-request-title">Service: {req.serviceName}</div>
          <p style={{ fontSize: '16px', marginBottom: '10px' }}>📍 Location: {req.location}</p>
          <p style={{ fontSize: '14px', opacity: 0.9 }}>Customer ID: {req.userId}</p>
          
          <div className="provider-buttons">
            <button className="provider-btn provider-btn-accept" onClick={handleAccept}>
              ✅ Accept Request
            </button>
            <button className="provider-btn provider-btn-reject" onClick={handleReject}>
              ❌ Reject Request
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}
